function safeText(v:any,max=180){return String(v??'').replace(/[\r\n|]+/g,' ').trim().slice(0,max)}
function normalize(v:any){return safeText(v,300).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'')}
function distanceKm(aLat:any,aLng:any,bLat:any,bLng:any){const lat1=Number(aLat),lng1=Number(aLng),lat2=Number(bLat),lng2=Number(bLng);if(![lat1,lng1,lat2,lng2].every(Number.isFinite))return null;const r=6371,toRad=(v:number)=>v*Math.PI/180,dLat=toRad(lat2-lat1),dLng=toRad(lng2-lng1),x=Math.sin(dLat/2)**2+Math.cos(toRad(lat1))*Math.cos(toRad(lat2))*Math.sin(dLng/2)**2;return r*2*Math.atan2(Math.sqrt(x),Math.sqrt(1-x))}
const UGO_PROVIDER_TIME_ZONE='America/Sao_Paulo'
function ugoLocalDay(value:any){try{const date=value instanceof Date?value:new Date(value);if(Number.isNaN(date.getTime()))return'';const parts=new Intl.DateTimeFormat('en-US',{timeZone:UGO_PROVIDER_TIME_ZONE,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(date),part=(type:string)=>parts.find(item=>item.type===type)?.value||'';return `${part('year')}-${part('month')}-${part('day')}`}catch{return''}}
function ugoLocalDateTime(value:any){try{const date=new Date(value);if(Number.isNaN(date.getTime()))return'';return new Intl.DateTimeFormat('es-AR',{timeZone:UGO_PROVIDER_TIME_ZONE,day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(date)}catch{return''}}
function requestedProviderCategory(message:string){const m=normalize(message);const aliases:[RegExp,string][]=[[/\b(jardinero|jardinera|jardineria|jardin)\b/,'jardineria'],[/\b(electricista|electricidad|electrico|electrica)\b/,'electricidad'],[/\b(plomero|plomera|plomeria|fontanero|fontaneria)\b/,'plomeria'],[/\b(limpieza|limpiador|limpiadora|faxina)\b/,'limpieza'],[/\b(pintor|pintora|pintura)\b/,'pintura'],[/\b(cerrajero|cerrajeria)\b/,'cerrajeria']];for(const[a,c]of aliases)if(a.test(m))return c;return null}
async function deterministicProviderReply(message:string,userId:string){
 if(!SUPABASE_SERVICE_KEY)return null
 const m=normalize(message),category=requestedProviderCategory(message),searchIntent=/\b(busca|buscame|buscar|hay|encontra|encontrame|cerca|disponible|quien|quienes|perfil|contame|hablame)\b/.test(m)
 if(!category&&!searchIntent)return null
 const sb=serviceClient(),[{data:client},{data:providers,error}]=await Promise.all([
  sb.from('usuarios').select('lat,lng').eq('id',userId).maybeSingle(),
  sb.from('proveedores_mapa').select('id,nombre,karma,servicios_completados,tarifa_base,online,disponible,estado_verificacion,categoria_nombre,bio,experiencia_anos,idiomas,lat,lng').eq('estado_verificacion','verificado').eq('online',true).eq('disponible',true).limit(50)
 ])
 if(error)return null
 const named=(providers||[]).filter((p:any)=>m.includes(normalize(p.nombre)))
 let matches=(named.length?named:(providers||[])).map((p:any)=>({...p,distance:distanceKm(client?.lat,client?.lng,p.lat,p.lng)}))
 if(category&&!named.length)matches=matches.filter((p:any)=>normalize(p.categoria_nombre).includes(category)||category.includes(normalize(p.categoria_nombre)))
 matches=matches.filter((p:any)=>p.distance==null||p.distance<=15).sort((a:any,b:any)=>(a.distance??99999)-(b.distance??99999)||Number(b.karma||0)-Number(a.karma||0)).slice(0,3)
 if(!matches.length){if(!category&&!named.length)return null;const label=category==='jardineria'?'jardineros':category||'profesionales';return{reply:`No encontré ${label} disponibles dentro de 15 km en este momento.`,action:'search_provider',category_hint:category}}
 const parts=matches.map((p:any)=>{const dist=p.distance!=null?` a ${p.distance.toFixed(2)} km`:'';const jobs=Number(p.servicios_completados||0);const exp=p.experiencia_anos!=null?`, ${Number(p.experiencia_anos)} años de experiencia`:'';return`${safeText(p.nombre,60)}${dist}, ${safeText(p.categoria_nombre||'profesional',50)}, karma ${Number(p.karma||0).toFixed(1)}, ${jobs} trabajo${jobs===1?'':'s'} completado${jobs===1?'':'s'}${exp}`})
 const intro=matches.length===1?'Sí. Encontré este profesional cerca tuyo:':'Sí. Encontré estos profesionales cerca tuyo:'
 return{reply:`${intro} ${parts.join('. ')}. ¿Querés que te cuente el perfil o elegir uno?`,action:'search_provider',category_hint:category}
}
async function hugoUgoContext(role:'client'|'provider',userId:string){
 if(!SUPABASE_SERVICE_KEY)return''
 const sb=serviceClient()
 try{
  if(role==='client'){
   const[{data:client},{data:providers,error},{data:categories}]=await Promise.all([
    sb.from('usuarios').select('lat,lng,zona').eq('id',userId).maybeSingle(),
    sb.from('proveedores_mapa').select('id,nombre,karma,servicios_completados,tarifa_base,online,disponible,estado_verificacion,categoria_nombre,categoria_emoji,bio,experiencia_anos,especialidades,idiomas,disponibilidad_horaria,ciudad_base,zona,lat,lng').eq('estado_verificacion','verificado').limit(30),
    sb.from('categorias').select('nombre,slug').eq('activa',true).order('nombre')
   ])
   if(error||!providers?.length)return'DATOS UGO PROFESIONALES: no hay profesionales verificables disponibles en este momento.'
   const enriched=(providers||[]).map((p:any)=>({...p,distance:distanceKm(client?.lat,client?.lng,p.lat,p.lng)})).sort((a:any,b:any)=>{const avail=Number(Boolean(b.online&&b.disponible))-Number(Boolean(a.online&&a.disponible));if(avail)return avail;const ad=a.distance??999999,bd=b.distance??999999;if(ad!==bd)return ad-bd;return Number(b.karma||0)-Number(a.karma||0)}).slice(0,15)
   const ids=enriched.map((p:any)=>p.id),{data:reviews}=await sb.from('resenas').select('proveedor_id,puntuacion,comentario,created_at').in('proveedor_id',ids).order('created_at',{ascending:false}).limit(45)
   const byProvider=new Map<string,{count:number,sum:number,comment:string}>();for(const r of reviews||[]){const k=String(r.proveedor_id),x=byProvider.get(k)||{count:0,sum:0,comment:''};x.count++;x.sum+=Number(r.puntuacion||0);if(!x.comment&&r.comentario)x.comment=safeText(r.comentario,90);byProvider.set(k,x)}
   const lines=enriched.map((p:any)=>{const rv=byProvider.get(String(p.id)),avg=rv?.count?(rv.sum/rv.count).toFixed(1):null,near=p.distance!=null&&p.distance<=15;return[`Nombre ${safeText(p.nombre,60)}`,`categoría ${safeText(p.categoria_nombre||'sin categoría',50)}`,`karma ${Number(p.karma||0).toFixed(1)}`,`${Number(p.servicios_completados||0)} trabajos completados`,`tarifa R$ ${Number(p.tarifa_base||0).toFixed(0)}/h`,p.online&&p.disponible?'disponible ahora':'no disponible ahora',p.distance!=null?`distancia aproximada ${p.distance.toFixed(2)} km del cliente${near?' (EN TU ZONA)':''}`:'distancia no disponible',p.experiencia_anos!=null?`${Number(p.experiencia_anos)} años de experiencia`:'',p.especialidades?`especialidades ${safeText(p.especialidades,100)}`:'',p.bio?`bio ${safeText(p.bio,120)}`:'',p.idiomas?`idiomas ${safeText(p.idiomas,70)}`:'',p.zona?`zona ${safeText(p.zona,70)}`:'',p.ciudad_base?`ciudad ${safeText(p.ciudad_base,70)}`:'',avg?`reseñas ${avg}/5 (${rv?.count})`:'',rv?.comment?`comentario reciente: ${rv.comment}`:''].filter(Boolean).join('; ')})
   return[`CATEGORIAS UGO REALES: ${(categories||[]).map((c:any)=>safeText(c.nombre||c.slug,50)).filter(Boolean).join(', ')||'sin catálogo disponible'}.`,`DATOS UGO PROFESIONALES REALES. Ubicación del cliente: ${client?.lat!=null&&client?.lng!=null?'disponible':'no disponible'}.`,client?.zona?`Zona declarada del cliente: ${safeText(client.zona,80)}`:'',`Ordenados por disponibilidad y cercanía:`,...lines].filter(Boolean).join('\n').slice(0,7000)
  }
  const activeStates=['asignado','en_camino','llegado','en_progreso','esperando_aprobacion']
  const today=ugoLocalDay(new Date())
  const[{data:providerJobs,error:providerJobsError},{count:completedExact},{count:allExact},{data:providerPayments,error:providerPaymentsError}]=await Promise.all([
   sb.from('servicios').select('id,numero,cliente_id,estado,descripcion,tarifa,ganancia_proveedor,moneda,created_at,programado_para,completado_at,cancelado_at,categoria:categorias(nombre)').eq('proveedor_id',userId).order('created_at',{ascending:false}).limit(200),
   sb.from('servicios').select('id',{count:'exact',head:true}).eq('proveedor_id',userId).eq('estado','completado'),
   sb.from('servicios').select('id',{count:'exact',head:true}).eq('proveedor_id',userId),
   sb.from('pagos').select('id,servicio_id,estado,metodo,monto_bruto,comision_ugo,ganancia_proveedor,moneda,created_at,fecha_confirmacion,liberado_at').eq('proveedor_id',userId).order('created_at',{ascending:false}).limit(250)
  ])
  const ownJobs=providerJobsError?[]:(providerJobs||[]),payments=providerPaymentsError?[]:(providerPayments||[])
  const completedToday=ownJobs.filter((job:any)=>job.estado==='completado'&&ugoLocalDay(job.completado_at||job.created_at)===today)
  const cancelledToday=ownJobs.filter((job:any)=>job.estado==='cancelado'&&ugoLocalDay(job.cancelado_at||job.created_at)===today)
  const activeOwn=ownJobs.filter((job:any)=>activeStates.includes(job.estado)||job.estado==='disputado')
  const paidToday=payments.filter((payment:any)=>payment.estado==='liberado'&&ugoLocalDay(payment.liberado_at||payment.fecha_confirmacion||payment.created_at)===today)
  const sum=(rows:any[],field:string)=>rows.reduce((total:number,row:any)=>total+Number(row?.[field]||0),0)
  const netToday=sum(paidToday,'ganancia_proveedor'),grossToday=sum(paidToday,'monto_bruto'),commissionToday=sum(paidToday,'comision_ugo')
  const cashToday=paidToday.filter((payment:any)=>payment.metodo==='efectivo'),electronicToday=paidToday.filter((payment:any)=>payment.metodo!=='efectivo')
  const recentCompleted=ownJobs.filter((job:any)=>job.estado==='completado').slice(0,8).map((job:any)=>{const category=Array.isArray(job.categoria)?job.categoria[0]:job.categoria;return`#${job.numero||String(job.id).slice(0,8)} · ${safeText(category?.nombre||'Servicio UGO',60)} · ${ugoLocalDateTime(job.completado_at||job.created_at)||'fecha no disponible'} · total R$ ${Number(job.tarifa||0).toFixed(2)} · neto proveedor R$ ${Number(job.ganancia_proveedor||0).toFixed(2)}`})
  const ownContext=[
   'DATOS UGO DEL PROVEEDOR AUTENTICADO:',
   `Fecha operativa local: ${today} (${UGO_PROVIDER_TIME_ZONE})`,
   `Trabajos registrados: ${Number(allExact??ownJobs.length)}; completados históricos: ${Number(completedExact??ownJobs.filter((job:any)=>job.estado==='completado').length)}; activos ahora: ${activeOwn.length}`,
   `TRABAJOS COMPLETADOS HOY: ${completedToday.length}; cancelados hoy: ${cancelledToday.length}`,
   `GANANCIA NETA HOY: R$ ${netToday.toFixed(2)}; cobro bruto hoy: R$ ${grossToday.toFixed(2)}; comisión UGO hoy: R$ ${commissionToday.toFixed(2)}`,
   `EFECTIVO HOY: ${cashToday.length} pago(s), bruto R$ ${sum(cashToday,'monto_bruto').toFixed(2)}, neto R$ ${sum(cashToday,'ganancia_proveedor').toFixed(2)}`,
   `ELECTRÓNICO HOY: ${electronicToday.length} pago(s), neto R$ ${sum(electronicToday,'ganancia_proveedor').toFixed(2)}`,
   recentCompleted.length?`ÚLTIMOS TRABAJOS COMPLETADOS:\n${recentCompleted.join('\n')}`:'No hay trabajos completados en el historial cargado.',
   'Cuando el proveedor pregunte “cuántos trabajos hice”, “cuánto gané hoy”, “qué hice hoy”, “qué pasó hoy” o por un trabajo anterior, respondé con estos datos. No digas que no tenés acceso al historial si la información está arriba.'
  ].join('\n')

  let service:any=null
  const active=activeOwn.find((job:any)=>activeStates.includes(job.estado))||null;service=active
  if(!service){const{data:offer}=await sb.from('ofertas_servicio').select('servicio_id').eq('proveedor_id',userId).eq('estado','pendiente').order('created_at',{ascending:false}).limit(1).maybeSingle();if(offer?.servicio_id){const{data:s}=await sb.from('servicios').select('id,numero,cliente_id,estado,descripcion,categoria_id,created_at').eq('id',offer.servicio_id).maybeSingle();service=s}}
  if(!service?.cliente_id)return ownContext.slice(0,7000)
  const clientId=String(service.cliente_id)
  const[{data:client},{data:cp},{data:jobs}]=await Promise.all([
   sb.from('usuarios').select('id,nombre,apellido,karma,servicios_completados,created_at').eq('id',clientId).maybeSingle(),
   sb.from('perfiles_cliente').select('idioma_preferido,contacto_preferido,horarios_preferidos,preferencias_servicio,observaciones').eq('usuario_id',clientId).maybeSingle(),
   sb.from('servicios').select('estado,created_at,completado_at,cancelado_at').eq('cliente_id',clientId).order('created_at',{ascending:false}).limit(100)
  ])
  const rows=jobs||[],completed=rows.filter((j:any)=>j.estado==='completado').length,cancelled=rows.filter((j:any)=>j.estado==='cancelado').length,activeCount=rows.filter((j:any)=>activeStates.includes(j.estado)||['buscando','ofrecido'].includes(j.estado)).length,total=rows.length,finished=completed+cancelled,completionRate=finished?Math.round(completed*100/finished):null
  const clientContext=[`DATOS UGO CLIENTE DE LA MISIÓN #${service.numero||''}:`, `Nombre: ${safeText([client?.nombre,client?.apellido].filter(Boolean).join(' ')||'Cliente UGO',80)}`,`Karma: ${Number(client?.karma||0).toFixed(1)}`,`Historial: ${total} pedidos registrados; ${completed} completados; ${cancelled} cancelados; ${activeCount} activos`,completionRate!=null?`Tasa de cierre sobre pedidos finalizados: ${completionRate}%`:'Sin suficientes pedidos finalizados para calcular tasa de cierre',client?.created_at?`Cliente desde: ${String(client.created_at).slice(0,10)}`:'',cp?.idioma_preferido?`Idioma preferido: ${safeText(cp.idioma_preferido,30)}`:'',cp?.contacto_preferido?`Contacto preferido: ${safeText(cp.contacto_preferido,40)}`:'',cp?.horarios_preferidos?`Horarios preferidos: ${safeText(cp.horarios_preferidos,100)}`:'',cp?.preferencias_servicio?`Preferencias de servicio: ${safeText(cp.preferencias_servicio,140)}`:'',cp?.observaciones?`Observaciones operativas: ${safeText(cp.observaciones,140)}`:'',`Trabajo actual: ${safeText(service.descripcion,180)}`].filter(Boolean).join('\n')
  return[ownContext,clientContext].join('\n\n').slice(0,8500)
 }catch(error){console.warn('Hugo UGO context failed',error);return''}
}

