 if(action==='callback'){if(req.method!=='GET')return res.status(405).json({error:'Método no permitido'});if(req.query?.error)return res.redirect(302,baseUrl(req)+'/?app=provider&calendar=cancelled');const code=String(req.query?.code||''),state=String(req.query?.state||'');if(!code||!state)throw Object.assign(new Error('Faltan datos de Google OAuth.'),{status:400});const userId=verifyCalendarState(state),sb=serviceClient(),{data:profile}=await sb.from('usuarios').select('tipo').eq('id',userId).maybeSingle();if(profile?.tipo!=='proveedor')throw Object.assign(new Error('Proveedor inválido.'),{status:403});const tokens=await googleToken(new URLSearchParams({code,client_id:String(process.env.GOOGLE_CALENDAR_CLIENT_ID||''),client_secret:String(process.env.GOOGLE_CALENDAR_CLIENT_SECRET||''),redirect_uri:calendarRedirectUri(req),grant_type:'authorization_code'})),access=String(tokens.access_token||'');if(!access)throw new Error('Google no devolvió access token.');const{data:existing}=await sb.from('proveedor_calendar_conexiones').select('refresh_token').eq('proveedor_id',userId).maybeSingle(),refresh=String(tokens.refresh_token||existing?.refresh_token||'');if(!refresh)throw Object.assign(new Error('Google no entregó permiso offline. Volvé a conectar.'),{status:502});let email:string|null=null;try{const info=await calendarJson(access,'https://www.googleapis.com/oauth2/v3/userinfo');email=String(info?.email||'')||null}catch{}const{error}=await sb.from('proveedor_calendar_conexiones').upsert({proveedor_id:userId,google_email:email,calendar_id:'primary',refresh_token:refresh,scope:String(tokens.scope||'')||null,updated_at:new Date().toISOString()},{onConflict:'proveedor_id'});if(error)throw error;await syncCalendarForProvider(sb,userId).catch(e=>console.warn('Calendar initial sync failed',e));return res.redirect(302,baseUrl(req)+'/?app=provider&calendar=connected')}
